<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Order extends Model{protected $fillable=['branch_id','user_id','customer_id','order_date','daily_number','status','type','scheduled_at','pending_expires_at','subtotal','discount','delivery_fee','total','courtesy','inventory_deducted','stock_warnings','notes'];protected function casts():array{return ['order_date'=>'date','scheduled_at'=>'datetime','pending_expires_at'=>'datetime','courtesy'=>'boolean','inventory_deducted'=>'boolean','stock_warnings'=>'array'];}public function customer(){return $this->belongsTo(Customer::class);}public function items(){return $this->hasMany(OrderItem::class);}public function payments(){return $this->hasMany(OrderPayment::class);}public function delivery(){return $this->hasOne(OrderDeliveryDetail::class);}public function histories(){return $this->hasMany(OrderStatusHistory::class);}public function reservations(){return $this->hasMany(StockReservation::class);}}
